scripts.dev:
node -e "const pkg = require('./package.json'); const fs = require('fs'); fs.writeFileSync('src/version.ts', '/** App version RICIS3-Expansion (synced with package.json). */
export const APP_VERSION = '' + pkg.version + '';
export const APP_NAME = 'RICIS-III Singularity Map';
export const APP_BUILD_LABEL = \`v\${APP_VERSION}\`;
');" && tsx server.ts

scripts.build:
node -e "const pkg = require('./package.json'); const fs = require('fs'); fs.writeFileSync('src/version.ts', '/** App version RICIS3-Expansion (synced with package.json). */
export const APP_VERSION = '' + pkg.version + '';
export const APP_NAME = 'RICIS-III Singularity Map';
export const APP_BUILD_LABEL = \`v\${APP_VERSION}\`;
');" && vite build && esbuild server.ts --bundle --platform=node --format=cjs --packages=external --sourcemap --outfile=dist/server.cjs
